r.vertexShaderSource:
in vec3 position3DHigh;
in vec3 position3DLow;
in float batchId;
in vec3 normal;
out vec3 v_normal;
void main()
{
vec4 p = czm_translateRelativeToEye(position3DHigh, position3DLow);
v_normal = normal;
gl_Position = czm_modelViewProjectionRelativeToEye * p;
}

r.fragmentShaderSource:
in vec3 v_normal;
vec4 getColor() { return vec4((v_normal + vec3(1.0)) * 0.5, 1.0); }

void main()
{
out_FragColor = getColor();
}

r.getFragmentShaderSource:
in vec3 v_normal;
vec4 getColor() { return vec4((v_normal + vec3(1.0)) * 0.5, 1.0); }

void main()
{
out_FragColor = getColor();
}

